-- migrations/0002_reviews_and_cron.sql
-- ============================================================================

-- justhairs — M1.5: appointment completion, review guard, rating views

-- ─────────────────────────────────────────────────────────────────────────────
-- Auto-complete past appointments
-- ─────────────────────────────────────────────────────────────────────────────
create or replace function complete_past_appointments()
returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_count integer;
begin
  update appointments
    set status = 'completed'
    where status = 'confirmed' and ends_at < now();
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

revoke execute on function complete_past_appointments() from anon, authenticated;
grant execute on function complete_past_appointments() to service_role;

-- Hourly cron. pg_cron must be enabled (Supabase → Database → Extensions).
create extension if not exists pg_cron;

select cron.unschedule('complete-past-appointments')
  where exists (select 1 from cron.job where jobname = 'complete-past-appointments');

select cron.schedule(
  'complete-past-appointments',
  '0 * * * *',
  $$select public.complete_past_appointments()$$
);

-- ─────────────────────────────────────────────────────────────────────────────
-- Reviews: only after a completed, owned appointment
-- ─────────────────────────────────────────────────────────────────────────────
drop policy if exists "reviews: own write" on reviews;

create policy "reviews: own insert" on reviews
  for insert to authenticated
  with check (
    customer_id = auth.uid()
    and exists (
      select 1 from appointments a
      where a.id = appointment_id
        and a.customer_id = auth.uid()
        and a.status = 'completed'
    )
  );

create policy "reviews: own update" on reviews
  for update to authenticated
  using (customer_id = auth.uid())
  with check (customer_id = auth.uid());

create policy "reviews: own delete" on reviews
  for delete to authenticated
  using (customer_id = auth.uid());

-- ─────────────────────────────────────────────────────────────────────────────
-- Rating aggregates
-- ─────────────────────────────────────────────────────────────────────────────
create or replace view service_ratings
with (security_invoker = true) as
  select service_id,
         round(avg(rating)::numeric, 1) as rating,
         count(*)::int as review_count
  from reviews
  where service_id is not null
  group by service_id;

create or replace view staff_ratings
with (security_invoker = true) as
  select staff_id,
         round(avg(rating)::numeric, 1) as rating,
         count(*)::int as review_count
  from reviews
  where staff_id is not null
  group by staff_id;

grant select on service_ratings, staff_ratings to anon, authenticated;

-- Public review feed — exposes only a first name + the service/staff name, so it
-- can run as owner (bypassing the profiles RLS) without leaking contact details.
create or replace view public_reviews
with (security_invoker = false) as
  select r.id,
         r.rating,
         r.comment,
         r.created_at,
         nullif(split_part(coalesce(p.full_name, ''), ' ', 1), '') as reviewer_first,
         s.name  as service_name,
         st.name as staff_name,
         r.service_id,
         r.staff_id
  from reviews r
  left join profiles p  on p.id  = r.customer_id
  left join services s  on s.id  = r.service_id
  left join staff    st on st.id = r.staff_id
  order by r.created_at desc;

grant select on public_reviews to anon, authenticated;

-- ============================================================================
-- migrations/0003_guest_booking_no_auth.sql
-- ============================================================================

-- justhairs — drop auth. Bookings are made by guests: contact details live on
-- the appointment row, and Stripe (or a "pay after the visit" choice) sets the
-- payment status. Nothing here touches existing seeded rows destructively.

-- ─────────────────────────────────────────────────────────────────────────────
-- appointments: guest-owned
-- ─────────────────────────────────────────────────────────────────────────────
alter table appointments
  alter column customer_id drop not null;

alter table appointments
  drop constraint if exists appointments_customer_id_fkey;

alter table appointments
  drop column if exists created_by;

alter table appointments
  add column if not exists customer_name  text,
  add column if not exists customer_email text,
  add column if not exists customer_phone text,
  add column if not exists confirmation_code text,
  add column if not exists payment_status text not null default 'unpaid'
    check (payment_status in ('unpaid', 'pay_later', 'paid')),
  add column if not exists stripe_session_id text;

create unique index if not exists appointments_confirmation_code_idx
  on appointments (confirmation_code);

-- Carry existing (auth-era) bookings' contact details onto the row itself,
-- while profiles is still around, so seeded reviews keep their reviewer names.
update appointments a
set customer_name  = coalesce(a.customer_name,  p.full_name),
    customer_email = coalesce(a.customer_email, p.email),
    customer_phone = coalesce(a.customer_phone, p.phone)
from profiles p
where p.id = a.customer_id;

update appointments set payment_status = 'pay_later' where payment_status = 'unpaid';

-- Short, unambiguous, human-readable reference (no 0/O/1/I).
create or replace function gen_confirmation_code()
returns text language plpgsql as $$
declare
  alphabet text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  code text := '';
  i int;
begin
  for i in 1..6 loop
    code := code || substr(alphabet, 1 + floor(random() * length(alphabet))::int, 1);
  end loop;
  return code;
end;
$$;

-- ─────────────────────────────────────────────────────────────────────────────
-- Booking engine: no auth.uid(), callable by anon
-- ─────────────────────────────────────────────────────────────────────────────
-- KNOWN ISSUE (CODE_REVIEW.md #1): the "not exists overlapping appointment"
-- check + insert below has no exclusion constraint or row lock behind it.
-- Under READ COMMITTED, two concurrent calls for the same staff+slot can
-- both pass the check before either commits -> a real double-booking. A
-- GiST exclusion constraint on (staff_id, tstzrange(starts_at, ends_at)) or
-- a SELECT ... FOR UPDATE here would close this.
create or replace function book_appointment(
  p_service_id uuid,
  p_staff_id   uuid,
  p_starts_at  timestamptz
)
returns appointments
language plpgsql security definer set search_path = public as $$
declare
  v_duration int;
  v_price    int;
  v_staff    uuid;
  v_ends     timestamptz;
  v_code     text;
  v_row      appointments;
begin
  select duration_min, price_cents into v_duration, v_price
  from services where id = p_service_id and active and online_booking;
  if v_duration is null then
    raise exception 'service not bookable' using errcode = 'P0001';
  end if;

  v_ends := p_starts_at + (v_duration || ' minutes')::interval;

  -- pick a concrete staff member from the still-available slots
  select s.staff_id into v_staff
  from get_available_slots(p_service_id, p_staff_id, (p_starts_at at time zone
    (select timezone from app_settings where id))::date) s
  where s.starts_at = p_starts_at
  limit 1;

  if v_staff is null then
    raise exception 'slot no longer available' using errcode = 'P0001';
  end if;

  -- retry a couple of times on the (astronomically unlikely) code collision
  for i in 1..5 loop
    begin
      v_code := gen_confirmation_code();
      insert into appointments
        (service_id, staff_id, starts_at, ends_at, status, price_cents, confirmation_code)
      values
        (p_service_id, v_staff, p_starts_at, v_ends, 'confirmed', v_price, v_code)
      returning * into v_row;
      return v_row;
    exception when unique_violation then
      -- try another code
    end;
  end loop;

  raise exception 'could not allocate a confirmation code' using errcode = 'P0001';
end;
$$;

-- Self-service reschedule/cancel required a signed-in owner — gone with auth.
drop function if exists reschedule_appointment(uuid, uuid, timestamptz);
drop function if exists cancel_appointment(uuid, text);

revoke execute on function book_appointment(uuid, uuid, timestamptz) from authenticated;
grant  execute on function book_appointment(uuid, uuid, timestamptz) to anon;

-- ─────────────────────────────────────────────────────────────────────────────
-- RLS: appointments carry PII (name/email/phone) now, so no anon read at all.
-- The app reads them with the service-role key server-side; get_available_slots
-- still sees them because it's SECURITY DEFINER.
-- ─────────────────────────────────────────────────────────────────────────────
drop policy if exists "appointments: own read"   on appointments;
drop policy if exists "appointments: admin write" on appointments;

-- Reviews: submission is removed from the app (display only). Drop the
-- auth-scoped write policies; keep public read for the rating views/feed.
drop policy if exists "reviews: own write"  on reviews;
drop policy if exists "reviews: own insert" on reviews;
drop policy if exists "reviews: own update" on reviews;
drop policy if exists "reviews: own delete" on reviews;

-- Reviews no longer belong to a signed-in profile — the reviewer's name comes
-- from the appointment's contact details.
alter table reviews alter column customer_id drop not null;
alter table reviews drop constraint if exists reviews_customer_id_fkey;

create or replace view public_reviews
with (security_invoker = false) as
  select r.id,
         r.rating,
         r.comment,
         r.created_at,
         nullif(split_part(coalesce(a.customer_name, ''), ' ', 1), '') as reviewer_first,
         s.name  as service_name,
         st.name as staff_name,
         r.service_id,
         r.staff_id
  from reviews r
  left join appointments a on a.id = r.appointment_id
  left join services s     on s.id = r.service_id
  left join staff    st    on st.id = r.staff_id
  order by r.created_at desc;

grant select on public_reviews to anon;

-- ============================================================================
-- migrations/0004_day_availability.sql
-- ============================================================================

-- One round trip for a whole date range. The booking UI needs availability for
-- ~2 weeks at once (to disable full days and show "next available" chips); doing
-- that as N separate calls made the date/time steps feel slow.

create or replace function get_day_availability(
  p_service_id uuid,
  p_staff_id   uuid,
  p_from       date,
  p_days       int
)
returns table (starts_at timestamptz, staff_id uuid)
language plpgsql stable security definer set search_path = public as $$
declare
  v_day date;
begin
  for i in 0..greatest(coalesce(p_days, 1) - 1, 0) loop
    v_day := p_from + i;
    return query
      select s.starts_at, s.staff_id
      from get_available_slots(p_service_id, p_staff_id, v_day) s;
  end loop;
end;
$$;

grant execute on function get_day_availability(uuid, uuid, date, int) to anon;

-- ============================================================================
-- migrations/0005_public_reviews_invoker.sql
-- ============================================================================

-- justhairs — public_reviews no longer needs SECURITY DEFINER.
--
-- The view ran as its owner only so it could read appointments.customer_name
-- (appointments has no anon read, it carries PII). Store the reviewer's first
-- name on the review itself instead, so the view reads only publicly readable
-- tables (reviews, services, staff) under the caller's own RLS.

alter table reviews add column if not exists reviewer_first text;

update reviews r
   set reviewer_first = nullif(split_part(coalesce(a.customer_name, ''), ' ', 1), '')
  from appointments a
 where a.id = r.appointment_id
   and r.reviewer_first is null;

create or replace view public_reviews
with (security_invoker = true) as
  select r.id,
         r.rating,
         r.comment,
         r.created_at,
         r.reviewer_first,
         s.name  as service_name,
         st.name as staff_name,
         r.service_id,
         r.staff_id
  from reviews r
  left join services s  on s.id  = r.service_id
  left join staff    st on st.id = r.staff_id
  order by r.created_at desc;

grant select on public_reviews to anon;

-- ============================================================================
-- migrations/0006_booking_integrity.sql
-- ============================================================================

-- justhairs — booking integrity and abuse hardening.
--   1. Double-booking is now impossible at the database level (CODE_REVIEW #1).
--   2. Abandoned, unpaid holds are released automatically.
--   3. The anon availability RPCs are bounded.
--   4. "Slot taken" has its own SQLSTATE so the app no longer string-matches.
--
-- NOTE: step 1 fails if existing rows already overlap for the same staff
-- member. Check first with:
--   select a.id, b.id from appointments a join appointments b
--     on a.staff_id = b.staff_id and a.id < b.id
--    and a.status in ('pending','confirmed','completed')
--    and b.status in ('pending','confirmed','completed')
--    and tstzrange(a.starts_at, a.ends_at, '[)') && tstzrange(b.starts_at, b.ends_at, '[)');

-- ─────────────────────────────────────────────────────────────────────────────
-- 1. No overlapping active appointments per staff member
-- ─────────────────────────────────────────────────────────────────────────────
create extension if not exists btree_gist with schema extensions;

alter table appointments
  drop constraint if exists appointments_no_overlap;

alter table appointments
  add constraint appointments_no_overlap
  exclude using gist (
    staff_id with =,
    tstzrange(starts_at, ends_at, '[)') with &&
  )
  where (staff_id is not null and status in ('pending', 'confirmed', 'completed'));

-- ─────────────────────────────────────────────────────────────────────────────
-- 4. book_appointment: custom SQLSTATE JH409 for "slot no longer available",
--    bounded start time, and the exclusion violation mapped to the same error
--    (two concurrent callers: one wins, the other gets JH409).
-- ─────────────────────────────────────────────────────────────────────────────
create or replace function book_appointment(
  p_service_id uuid,
  p_staff_id   uuid,
  p_starts_at  timestamptz
)
returns appointments
language plpgsql security definer set search_path = public as $$
declare
  v_duration int;
  v_price    int;
  v_staff    uuid;
  v_ends     timestamptz;
  v_code     text;
  v_row      appointments;
begin
  if p_starts_at is null
     or p_starts_at <= now()
     or p_starts_at > now() + interval '90 days' then
    raise exception 'slot no longer available' using errcode = 'JH409';
  end if;

  select duration_min, price_cents into v_duration, v_price
  from services where id = p_service_id and active and online_booking;
  if v_duration is null then
    raise exception 'service not bookable' using errcode = 'P0001';
  end if;

  v_ends := p_starts_at + (v_duration || ' minutes')::interval;

  select s.staff_id into v_staff
  from get_available_slots(p_service_id, p_staff_id, (p_starts_at at time zone
    (select timezone from app_settings where id))::date) s
  where s.starts_at = p_starts_at
  limit 1;

  if v_staff is null then
    raise exception 'slot no longer available' using errcode = 'JH409';
  end if;

  for i in 1..5 loop
    begin
      v_code := gen_confirmation_code();
      insert into appointments
        (service_id, staff_id, starts_at, ends_at, status, price_cents, confirmation_code)
      values
        (p_service_id, v_staff, p_starts_at, v_ends, 'confirmed', v_price, v_code)
      returning * into v_row;
      return v_row;
    exception
      when unique_violation then
        -- confirmation-code collision: try another code
        null;
      when exclusion_violation then
        raise exception 'slot no longer available' using errcode = 'JH409';
    end;
  end loop;

  raise exception 'could not allocate a confirmation code' using errcode = 'P0001';
end;
$$;

revoke execute on function book_appointment(uuid, uuid, timestamptz) from public;
grant  execute on function book_appointment(uuid, uuid, timestamptz) to anon;

-- ─────────────────────────────────────────────────────────────────────────────
-- 3. Bounded availability range for anon callers
-- ─────────────────────────────────────────────────────────────────────────────
create or replace function get_day_availability(
  p_service_id uuid,
  p_staff_id   uuid,
  p_from       date,
  p_days       int
)
returns table (starts_at timestamptz, staff_id uuid)
language plpgsql stable security definer set search_path = public as $$
declare
  v_day  date;
  v_days int := least(greatest(coalesce(p_days, 1), 1), 31);
begin
  -- Nothing to offer outside the bookable window; also keeps the work bounded.
  if p_from is null
     or p_from < current_date - 1
     or p_from > current_date + 90 then
    return;
  end if;

  for i in 0..v_days - 1 loop
    v_day := p_from + i;
    return query
      select s.starts_at, s.staff_id
      from get_available_slots(p_service_id, p_staff_id, v_day) s;
  end loop;
end;
$$;

revoke execute on function get_day_availability(uuid, uuid, date, int) from public;
grant  execute on function get_day_availability(uuid, uuid, date, int) to anon;

-- ─────────────────────────────────────────────────────────────────────────────
-- 2. Release abandoned holds
-- ─────────────────────────────────────────────────────────────────────────────
-- A hold is an appointment the guest started but never settled: still
-- 'unpaid' (not pay_later, not paid) with no Stripe Checkout session open.
-- Rows with a Checkout session are left alone — the guest may still be paying.
create or replace function release_stale_holds()
returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_count integer;
begin
  delete from appointments
   where payment_status = 'unpaid'
     and stripe_session_id is null
     and created_at < now() - interval '15 minutes';
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

revoke execute on function release_stale_holds() from public, anon, authenticated;
grant  execute on function release_stale_holds() to service_role;

select cron.unschedule('release-stale-holds')
  where exists (select 1 from cron.job where jobname = 'release-stale-holds');

select cron.schedule(
  'release-stale-holds',
  '*/5 * * * *',
  $$select public.release_stale_holds()$$
);

-- ─────────────────────────────────────────────────────────────────────────────
-- Default EXECUTE goes to PUBLIC, so revoking from anon/authenticated alone
-- (as 0002 did) leaves the cron-only function callable. Close that.
-- ─────────────────────────────────────────────────────────────────────────────
revoke execute on function complete_past_appointments() from public;
grant  execute on function complete_past_appointments() to service_role;

